+{
+  double mx = 0, my = 0, vx = 0, vy = 0;
+  double denom;
+  int i;
+
+  for (i = 0; i < n; i++)
+    mx += x[i];
+  mx /= n;
+  for (i = 0; i < m; i++)
+    my += y[i];
+  my /= m;
+
+  for (i = 0; i < n; i++)
+    vx += (x[i] - mx) * (x[i] - mx);
+  vx /= (n - 1);
+  for (i = 0; i < m; i++)
+    vy += (y[i] - my) * (y[i] - my);
+  vy /= (m - 1);
